// Code node "Catálogo de produtos".
//
// Para cadastrar um produto novo, adicione um objeto nesta lista e salve o
// workflow. A ordem importa: quando um post bate com mais de um item, o
// primeiro da lista vira o título do alerta.
//
// Campos:
//   id         identificador curto e único
//   label      nome exibido no alerta
//   model      regex do modelo (texto já normalizado: minúsculo, sem acento)
//   excludeAfter  variantes descartadas quando aparecem logo depois do modelo
//   requireAll lista de regex que também precisam aparecer no texto
//   size       polegadas exigidas (TVs)
//   minPrice   abaixo disso é acessório (capa, película, suporte) e é ignorado
//   maxPrice   teto de preço; parcelado conta pelo total
//   active     false pausa o produto sem apagar

const PHONE = { minPrice: 900, maxPrice: 5000 };
const TV = { minPrice: 1200, maxPrice: 5000 };

const catalog = [
  { id: 'iphone-16e', label: 'iPhone 16e', model: 'iphone\\s?16\\s?e', ...PHONE },
  {
    id: 'iphone-17',
    label: 'iPhone 17',
    model: 'iphone\\s?17',
    excludeAfter: ['e', 'pro', 'air', 'plus', 'max'],
    ...PHONE,
  },
  {
    id: 'galaxy-s26',
    label: 'Samsung Galaxy S26',
    model: 's\\s?26',
    excludeAfter: ['fe', '\\+', 'plus', 'ultra', 'edge'],
    requireAll: ['galaxy|samsung'],
    ...PHONE,
  },
  {
    id: 'tv-lg-mrgb85',
    label: 'Smart TV LG 55" MRGB85',
    model: 'mrgb\\s?85',
    requireAll: ['\\blg\\b'],
    size: 55,
    ...TV,
  },
  {
    id: 'tv-lg-qned',
    label: 'Smart TV LG 55" QNED',
    model: 'qned',
    requireAll: ['\\blg\\b'],
    size: 55,
    ...TV,
  },
  {
    id: 'moto-edge-70',
    label: 'Motorola Edge 70',
    model: 'edge\\s?70',
    excludeAfter: ['fusion', 'pro'],
    requireAll: ['motorola|\\bmoto\\b'],
    ...PHONE,
  },
  {
    id: 'galaxy-a57-256',
    label: 'Samsung Galaxy A57 256 GB',
    model: 'a\\s?57',
    requireAll: ['galaxy|samsung', '\\b256\\s?(gb|g)\\b'],
    ...PHONE,
  },
  // Lote de 21/11. Tetos calibrados pelos preços vistos nos canais em
  // novembro; minPrice separa o produto de capas, suportes e acessórios.
  // Compras planejadas (21/11): highlight marca o alerta e refPrice é a faixa
  // de preço pesquisada fora dos canais, usada para dizer se a oferta é boa.
  {
    id: 'galaxy-a17-256',
    label: 'Samsung Galaxy A17 256 GB',
    model: 'a\\s?17',
    requireAll: ['galaxy|samsung', '\\b256\\s?(gb|g)\\b'],
    // A versão de 256 GB é 5G; post que diga 4G é outro aparelho
    excludeAny: ['(?<![a-z0-9])4g(?![a-z0-9])'],
    // Post que cita outra RAM é descartado; sem citação, alerta com aviso
    ram: 8,
    minPrice: 900,
    maxPrice: 1600,
    refPrice: [1300, 1600],
    highlight: true,
  },
  {
    id: 'galaxy-a07-128',
    label: 'Samsung Galaxy A07 128 GB',
    model: 'a\\s?07',
    requireAll: ['galaxy|samsung', '\\b128\\s?(gb|g)\\b'],
    minPrice: 400,
    maxPrice: 800,
    refPrice: [600, 800],
    highlight: true,
  },
  // Logitech MX Master (22/11). O 4 é o preferido e tem entrada própria;
  // a segunda pega 3S, 3 e 2S e exclui o 4 para não alertar em dobro.
  // Tetos: lançamento do 4 no Brasil a R$ 799 (já visto a R$ 679,90);
  // 3S em promoção costuma ficar entre R$ 420 e R$ 650.
  {
    id: 'mx-master-4',
    label: 'Logitech MX Master 4',
    model: 'mx\\s?master\\s?4',
    minPrice: 200,
    maxPrice: 800,
  },
  {
    id: 'mx-master',
    label: 'Logitech MX Master (3S e anteriores)',
    model: 'mx\\s?master',
    excludeAfter: ['4'],
    minPrice: 200,
    maxPrice: 550,
  },
  {
    id: 'echo-dot',
    label: 'Echo Dot (5ª geração ou mais recente)',
    model: 'echo\\s?dot',
    excludeAfter: ['max'],
    // Muitos posts não citam a geração; exclui só as antigas quando citadas
    excludeAny: ['(?<![a-z0-9])[1-4]\\s?a?\\s?geracao'],
    minPrice: 150,
    maxPrice: 300,
  },
  {
    id: 'kindle',
    label: 'Kindle',
    model: 'kindle',
    minPrice: 300,
    maxPrice: 800,
  },
  {
    id: 'airfryer',
    label: 'Air Fryer',
    model: 'air\\s?fryer|fritadeira\\s(?:eletrica|sem oleo)',
    // Air fryer pequena sai por ~R$ 116; papel e forma custam R$ 30 a 40
    minPrice: 80,
    maxPrice: 450,
  },
  {
    id: 'mochila',
    label: 'Mochila',
    model: 'mochila',
    minPrice: 50,
    maxPrice: 300,
  },
].map((p) => ({ active: true, ...p }));

const settings = {
  // Posts publicados há mais tempo que isso são ignorados. Evita alerta de
  // oferta velha quando o listener volta de uma queda e recupera o atraso.
  maxAgeMinutes: 60,
  // Posts recuperados pela reconciliação do listener (PC desligado à noite,
  // VM restaurada) passam do corte acima até este limite e chegam marcados
  // como retroativos.
  maxReplayHours: 16,
};

// Alterações feitas pelo bot (/pausar, /teto, /add) ficam no static data
// do workflow e são aplicadas por cima da lista acima a cada execução.
// A lista deste arquivo continua sendo a base: editar aqui e publicar
// não apaga o que foi ajustado pelo bot.
function applyOverrides(base, store) {
  const overrides = store.overrides || {};
  const merged = [...base, ...(store.custom || []).map((p) => ({ ...p, custom: true }))];
  return merged.map((p) => ({ ...p, ...(overrides[p.id] || {}) }));
}

const store = typeof $getWorkflowStaticData === 'function' ? $getWorkflowStaticData('global') : {};

return [{ json: { catalog: applyOverrides(catalog, store), baseIds: catalog.map((p) => p.id), settings } }];

// Code node "Analisar oferta".
//
// Entrada: o post enviado pelo listener (corpo do Webhook) e o catálogo.
// Saída: zero itens (post sem interesse) ou um item com a oferta já
// estruturada: produtos que bateram, preço, cupom, link e descrição.
//
// O arquivo roda igual dentro do n8n e no harness de teste local
// (n8n/tests/run.mjs): as funções puras ficam no topo e a "cola" com o n8n
// só executa quando $input existe.

const NON_OFFER_HOSTS = /^https?:\/\/(t\.me|telegram\.me|chat\.whatsapp\.com|wa\.me|instagram\.com)\b/i;
const COUPON_STOPWORDS = new Set([
  'DE', 'DO', 'NO', 'NA', 'OFF', 'APLICADO', 'CARRINHO', 'SITE', 'APP', 'PIX',
  'DESCONTO', 'CUPOM', 'CUPONS', 'ATIVO', 'ATIVE', 'RESGATE', 'AQUI', 'USE',
]);

// Alguns canais inserem caracteres invisíveis no meio das palavras
// ("Mon⁠itor") para dificultar cópia e busca. Sem remover, "iphone"
// vira "iph one" depois da normalização e nada bate.
function stripInvisible(text) {
  return String(text || '').replace(/[­​-‏⁠-⁯﻿]/g, '');
}

function normalize(text) {
  return text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9+]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function parseBRL(raw) {
  // "4.299,00" -> 4299 ; "4299" -> 4299 ; "4.299" -> 4299
  const clean = raw.replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  const value = parseFloat(clean);
  return Number.isFinite(value) ? value : null;
}

function extractPrices(text) {
  const t = text.replace(/ /g, ' ');
  const cash = [];
  const installments = [];
  const re = /r\$\s*([\d.]+(?:,\d{1,2})?)/gi;
  let m;
  while ((m = re.exec(t)) !== null) {
    const value = parseBRL(m[1]);
    if (value === null) continue;
    const before = t.slice(Math.max(0, m.index - 30), m.index).toLowerCase();
    const after = t.slice(m.index + m[0].length, m.index + m[0].length + 20).toLowerCase();

    // Valores de desconto/cupom/cashback, que não são preço do produto
    if (/^\s*(off|de desconto|em cupom|de cashback)/.test(after)) continue;
    if (/(cupom|desconto|cashback|economi[zs]e|economia|off)\s*(de)?\s*$/.test(before)) continue;

    const inst = before.match(/(\d{1,2})\s*x\s*(sem juros\s*)?(de)?\s*$/);
    if (inst) {
      const times = parseInt(inst[1], 10);
      installments.push({ times, each: value, total: +(value * times).toFixed(2) });
      continue;
    }
    // Preço antigo riscado: "de R$ 6.999 por R$ 4.999"
    if (/(^|\s)de\s*$/.test(before) && /por\s*r\$/i.test(t)) continue;
    cash.push(value);
  }

  // Preço escrito sem "R$": "saindo a 5273", "💰 5.273 no pix"
  const bare = /(?:saindo a|saindo por|sai por|sai a|por apenas|💰)\s*([\d][\d.]*(?:,\d{1,2})?)(?!\s*x)/gi;
  while ((m = bare.exec(t)) !== null) {
    const value = parseBRL(m[1]);
    if (value !== null && value >= 10) cash.push(value);
  }
  return { cash, installments };
}

function extractCoupon(post) {
  const valid = (c) => /^[A-Z0-9][A-Z0-9_-]{3,24}$/i.test(c) && /\d|[A-Z]{4,}/.test(c) && !COUPON_STOPWORDS.has(c.toUpperCase());

  // 1) Cupom formatado como `código` no Telegram (toque para copiar)
  const fromEntities = (post.codes || []).map((c) => c.trim()).filter((c) => valid(c) && !/^\d+$/.test(c));
  if (fromEntities.length) return fromEntities[0];

  // 2) "Cupom: XPTO10", "cupom XPTO10", "use o cupom XPTO10"
  const re = /cupom\s*(?:de\s+r\$\s*[\d.,]+\s*(?:off)?)?\s*[:\-–]?\s*["“'`]?([A-Za-z0-9_-]{4,25})/gi;
  let m;
  while ((m = re.exec(post.text || '')) !== null) {
    const code = m[1];
    if (valid(code) && code === code.toUpperCase()) return code;
  }
  return null;
}

// Linhas com link que não é o produto: cadastro no Prime, grupos, canais
const NON_OFFER_LINE = /prime|cadastr|teste por|gr[aá]tis por|grupo|whatsapp|canal|instagram|sigam?/i;
const OFFER_LINE = /compr[ea]|link|aqui|site|🛒/i;

function pickOfferUrl(post) {
  const text = post.text || '';
  const lines = text.split('\n');
  const lineOf = (url) => lines.find((l) => l.includes(url)) || '';
  const inText = text.match(/https?:\/\/[^\s)]+/g) || [];
  const all = [...(post.urls || []), ...inText]
    .filter((u, i, arr) => /^https?:\/\//i.test(u) && !NON_OFFER_HOSTS.test(u) && arr.indexOf(u) === i);

  const usable = all.filter((u) => !NON_OFFER_LINE.test(lineOf(u)) || OFFER_LINE.test(lineOf(u)) && !/prime/i.test(lineOf(u)));
  const preferred = usable.find((u) => OFFER_LINE.test(lineOf(u)));
  return preferred || usable[0] || all[0] || null;
}

function extractTitle(text, product) {
  const lines = (text || '')
    .split('\n')
    .map((l) => l
      .replace(/[\p{Extended_Pictographic}‍️]/gu, '')
      // "Produto X | De R$ 2.119 Por R$ 1.719": mantém só o produto
      .replace(/\s*\|?\s*(de\s*)?r\$.*$/i, '')
      .replace(/\s+/g, ' ')
      .trim())
    .filter((l) => l.length > 3 && !/^https?:\/\//i.test(l));
  // A primeira linha costuma ser comentário ("Baixouuuu!!"); a linha com o
  // modelo do produto é o título de verdade
  if (product) {
    const model = buildMatcher(product).model;
    const withModel = lines.find((l) => model.test(normalize(l)));
    if (withModel) return withModel;
  }
  return lines[0] || '';
}

function buildMatcher(product) {
  const variants = (product.excludeAfter || []).map((v) => (/\w$/.test(v) ? `${v}\\b` : v));
  // Modelo terminado em número não pode emendar outro dígito (s26 != s260)
  let lookahead = /\d$/.test(product.model) ? '(?!\\d)' : '';
  if (variants.length) lookahead += `(?!\\s?(?:${variants.join('|')}))`;
  return {
    // Não precedido de letra: aceita modelo colado no tamanho ("55mrgb85")
    model: new RegExp(`(?<![a-z])(?:${product.model})${lookahead}`),
    requireAll: (product.requireAll || []).map((r) => new RegExp(r)),
    excludeAny: (product.excludeAny || []).map((r) => new RegExp(r)),
    size: product.size ? new RegExp(`\\b${product.size}(?!\\d)`) : null,
  };
}

// RAM citada no post, em GB. Valores até 16 GB são RAM (armazenamento começa
// em 64). Ignora RAM virtual pelo que vem depois do número ("8GB RAM Plus",
// "16GB RAM Boost"). Um "+" antes do número não basta para descartar:
// "256GB + 8GB de RAM" é RAM real.
function ramMentions(norm) {
  const found = [];
  const re = /(?<![0-9])(\d{1,2})\s?gb(?!\s?(?:de\s)?ram\s?(?:plus|boost|virtual|extra))/g;
  let m;
  while ((m = re.exec(norm)) !== null) {
    const v = parseInt(m[1], 10);
    if (v >= 2 && v <= 16) found.push(v);
  }
  return [...new Set(found)];
}

function matchProducts(post, catalog) {
  const textNoPrices = (post.text || '').replace(/r\$\s*[\d.,]+/gi, ' ');
  const norm = normalize(textNoPrices);
  return catalog.filter((p) => {
    if (p.active === false) return false;
    const m = buildMatcher(p);
    if (!m.model.test(norm)) return false;
    if (!m.requireAll.every((r) => r.test(norm))) return false;
    if (m.excludeAny.some((r) => r.test(norm))) return false;
    // RAM exigida: descarta só quando o post cita outra; sem citação, passa
    // e o alerta avisa para conferir
    if (p.ram) {
      const rams = ramMentions(norm);
      if (rams.length && !rams.includes(p.ram)) return false;
    }
    if (m.size && !m.size.test(norm)) return false;
    return true;
  });
}

function ageMinutes(post, now) {
  const posted = Date.parse(post.posted_at);
  return Number.isFinite(posted) ? (now - posted) / 60000 : 0;
}

function analyze(rawPost, catalog, settings = {}, now = Date.now()) {
  const post = { ...rawPost, text: stripInvisible(rawPost.text), codes: (rawPost.codes || []).map(stripInvisible) };
  const maxAge = settings.maxAgeMinutes ?? Infinity;
  const maxReplay = (settings.maxReplayHours ?? 0) * 60;
  const age = ageMinutes(post, now);
  const retro = age > maxAge;
  if (retro && !(post.replay && age <= maxReplay)) return { status: 'antigo', ageMinutes: Math.round(age) };

  const matched = matchProducts(post, catalog);
  if (!matched.length) return { status: 'sem_produto' };

  const { cash, installments } = extractPrices(post.text || '');
  const primary = matched[0];
  const plausibleCash = cash.filter((v) => v >= primary.minPrice);
  const plausibleInst = installments.filter((i) => i.total >= primary.minPrice);

  // Só valores abaixo do piso apareceram: é acessório (capa, película...)
  if ((cash.length || installments.length) && !plausibleCash.length && !plausibleInst.length) {
    return { status: 'acessorio', matched: matched.map((p) => p.id) };
  }

  const candidates = [...plausibleCash, ...plausibleInst.map((i) => i.total)];
  const price = candidates.length ? Math.min(...candidates) : null;
  const installment = plausibleInst.sort((a, b) => a.total - b.total)[0] || null;

  if (price !== null && price > primary.maxPrice) {
    return { status: 'acima_do_teto', matched: matched.map((p) => p.id), price };
  }

  return {
    status: 'alerta',
    products: matched.map((p) => ({ id: p.id, label: p.label })),
    highlight: Boolean(primary.highlight),
    ramWarning: primary.ram && !ramMentions(normalize(post.text.replace(/r\$\s*[\d.,]+/gi, ' '))).length
      ? `RAM não informada no post: confira se é ${primary.ram} GB`
      : null,
    refPrice: primary.refPrice || null,
    price,
    installment,
    coupon: extractCoupon(post),
    offerUrl: pickOfferUrl(post),
    title: extractTitle(post.text, primary),
    source: post.source,
    postUrl: post.post_url,
    postedAt: post.posted_at,
    messageId: post.message_id,
    retro,
  };
}

if (typeof module !== 'undefined') {
  module.exports = { stripInvisible, normalize, ramMentions, parseBRL, extractPrices, extractCoupon, pickOfferUrl, extractTitle, matchProducts, analyze };
}

if (typeof $input !== 'undefined') {
  const { catalog, settings } = $('Catálogo de produtos').first().json;
  const post = $('Webhook').first().json.body;
  const result = analyze(post, catalog, settings);
  return [{ json: result }];
}

// Code node "Deduplicar".
//
// A mesma oferta costuma aparecer nos dois canais, ou ser repostada no mesmo
// canal com outro link de afiliado. A chave é produto + preço arredondado:
// links mudam entre canais, preço e produto não. Sem preço, a chave cai para
// o link da oferta.
//
// O estado vive no static data do workflow, que o n8n só persiste em
// execuções de produção (workflow ativo). Em teste manual, nada é lembrado.

const WINDOW_HOURS = 12;

function dedupKey(offer) {
  const product = offer.products[0].id;
  const anchor = offer.price !== null ? `R$${Math.round(offer.price)}` : offer.offerUrl || offer.postUrl;
  return `${product}|${anchor}`;
}

function isDuplicate(store, offer, now = Date.now()) {
  store.seen = store.seen || {};
  const cutoff = now - WINDOW_HOURS * 3600 * 1000;
  for (const [k, ts] of Object.entries(store.seen)) {
    if (ts < cutoff) delete store.seen[k];
  }
  const key = dedupKey(offer);
  if (store.seen[key]) return true;
  store.seen[key] = now;
  return false;
}

if (typeof module !== 'undefined') module.exports = { dedupKey, isDuplicate };

if (typeof $input !== 'undefined') {
  const store = $getWorkflowStaticData('global');
  return $input.all().filter((item) => !isDuplicate(store, item.json));
}

// Code node "Formatar alerta".
//
// Monta a mensagem no subset de HTML aceito pela Bot API (b, i, a, code) e os
// dois botões: link da oferta e post original no canal.

const TZ = 'America/Sao_Paulo';

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function brl(value) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
}

function stamp(date) {
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
  }).format(date).replace(',', '');
}

// Compara com a faixa pesquisada fora dos canais: diz se é oferta de verdade
function refPriceLine(price, refPrice) {
  if (!Array.isArray(refPrice) || refPrice.length !== 2) return null;
  const [low, high] = refPrice;
  const range = `${brl(low).replace(/,00$/, '')} a ${brl(high).replace(/,00$/, '')}`;
  if (price < low) {
    const pct = Math.round((1 - price / low) * 100);
    return `📊 <b>${pct}% abaixo</b> da sua faixa (${range}) 🔥`;
  }
  return `📊 Dentro da sua faixa (${range})`;
}

function formatAlert(offer, now = new Date()) {
  const [main, ...others] = offer.products;
  const lines = [];
  if (offer.highlight) lines.push('⭐⭐ <b>COMPRA PLANEJADA</b> ⭐⭐');
  if (offer.retro && offer.postedAt) {
    lines.push(`⏪ <i>Retroativo: postado em ${stamp(Date.parse(offer.postedAt))}, pode ter esgotado</i>`);
  }
  lines.push(`🎯 <b>${esc(main.label)}</b>`);
  if (others.length) lines.push(`<i>também: ${esc(others.map((p) => p.label).join(', '))}</i>`);
  if (offer.title) lines.push(esc(offer.title));
  if (offer.ramWarning) lines.push(`⚠️ <i>${esc(offer.ramWarning)}</i>`);
  lines.push('');

  if (offer.price !== null) {
    let priceLine = `💰 <b>${brl(offer.price)}</b>`;
    const inst = offer.installment;
    if (inst && Math.abs(inst.total - offer.price) > 0.01) {
      priceLine += ` ou ${inst.times}x de ${brl(inst.each)}`;
    } else if (inst) {
      priceLine += ` em ${inst.times}x de ${brl(inst.each)}`;
    }
    lines.push(priceLine);
    const ref = refPriceLine(offer.price, offer.refPrice);
    if (ref) lines.push(ref);
  } else {
    lines.push('💰 <i>preço não identificado no post</i>');
  }

  lines.push(offer.coupon ? `🎟 Cupom: <code>${esc(offer.coupon)}</code>` : '🎟 Sem cupom');
  lines.push(`📣 Fonte: <b>${esc(offer.source?.title)}</b>`);
  lines.push(`🕒 ${stamp(now)}`);

  const offerUrl = offer.offerUrl || offer.postUrl;
  return {
    text: lines.join('\n'),
    offerUrl,
    postUrl: offer.postUrl,
  };
}

if (typeof module !== 'undefined') module.exports = { formatAlert, refPriceLine, esc, brl, stamp };

if (typeof $input !== 'undefined') {
  return $input.all().map((item) => ({ json: { ...item.json, ...formatAlert(item.json) } }));
}

// Code node "Processar comando".
//
// Recebe um comando do bot (repassado pelo listener) e altera o catálogo
// guardado no static data do workflow. Devolve o texto de resposta.
//
//   /produtos                         lista com status e teto
//   /pausar <id>   /ativar <id>       liga e desliga um produto
//   /teto <id> <valor>                muda o teto de preço
//   /minimo <id> <valor>              muda o preço mínimo (abaixo é acessório)
//   /add <termos> [-excluir] [teto=N] [min=N]   cria um produto
//   /remover <id>                     apaga um produto criado por /add
//   /status                           saúde do listener
//   /ajuda

const DEFAULT_MAX = 5000;
const DEFAULT_MIN = 300;
const TZ = 'America/Sao_Paulo';

const HELP = [
  '<b>Comandos do radar</b>',
  '/produtos: lista produtos, status e teto',
  '/pausar <code>id</code> e /ativar <code>id</code>',
  '/teto <code>id</code> <code>valor</code>: ex. <code>/teto iphone-17 4500</code>',
  '/minimo <code>id</code> <code>valor</code>: ex. <code>/minimo controle 200</code>',
  '/add <code>termos</code>: ex. <code>/add galaxy s25 fe -ultra teto=2500</code>',
  '   termos com "-" excluem; teto e min em reais',
  '/remover <code>id</code>: só produtos criados por /add',
  '/status: saúde do listener',
].join('\n');

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function normalize(text) {
  return String(text).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9+]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function reEscape(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function brl(v) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(v);
}

function parseMoney(s) {
  const v = parseFloat(String(s).replace(/\./g, '').replace(',', '.'));
  return Number.isFinite(v) && v > 0 ? v : null;
}

function ago(iso, now) {
  if (!iso) return 'nunca';
  const min = Math.round((now - Date.parse(iso)) / 60000);
  if (min < 60) return `há ${min} min`;
  return `há ${Math.floor(min / 60)}h${String(min % 60).padStart(2, '0')}`;
}

function buildCustomProduct(args) {
  const positives = [];
  const negatives = [];
  let maxPrice = DEFAULT_MAX;
  let minPrice = DEFAULT_MIN;
  for (const raw of args) {
    const kv = raw.match(/^(teto|min)=(.+)$/i);
    if (kv) {
      const v = parseMoney(kv[2]);
      if (v === null) return { error: `Valor inválido em <code>${esc(raw)}</code>.` };
      if (kv[1].toLowerCase() === 'teto') maxPrice = v; else minPrice = v;
    } else if (raw.startsWith('-') && raw.length > 1) {
      negatives.push(normalize(raw.slice(1)));
    } else {
      positives.push(raw);
    }
  }
  const terms = positives.map(normalize).filter(Boolean);
  if (!terms.length) return { error: 'Informe ao menos um termo. Ex.: <code>/add galaxy s25 fe</code>' };

  const word = (t) => `(?<![a-z0-9])${reEscape(t).replace(/ /g, '\\s?')}(?![a-z0-9])`;
  // O termo com número costuma ser o mais específico (s25, 16e, a57)
  const modelIdx = Math.max(0, terms.findIndex((t) => /\d/.test(t)));
  return {
    product: {
      id: terms.join('-').replace(/[^a-z0-9-]/g, ''),
      label: positives.join(' '),
      model: reEscape(terms[modelIdx]).replace(/ /g, '\\s?'),
      requireAll: terms.filter((_, i) => i !== modelIdx).map(word),
      excludeAny: negatives.filter(Boolean).map(word),
      minPrice,
      maxPrice,
      active: true,
    },
  };
}

function handleCommand(text, store, ctx, now = Date.now()) {
  store.overrides = store.overrides || {};
  store.custom = store.custom || [];
  const [rawCmd, ...args] = String(text || '').trim().split(/\s+/);
  const cmd = rawCmd.toLowerCase().replace(/@.*$/, '');
  const catalog = ctx.catalog || [];
  const find = (id) => catalog.find((p) => p.id === (id || '').toLowerCase());
  const unknown = (id) => `Produto <code>${esc(id || '?')}</code> não encontrado. Veja /produtos.`;

  switch (cmd) {
    case '/start':
    case '/ajuda':
    case '/help':
      return HELP;

    case '/produtos': {
      if (!catalog.length) return 'Catálogo vazio.';
      const lines = catalog.map((p) =>
        `${p.active === false ? '⏸' : '🟢'} <code>${esc(p.id)}</code> ${esc(p.label)} · ${brl(p.minPrice || 0)} a ${brl(p.maxPrice)}${p.custom ? ' · <i>via /add</i>' : ''}`);
      return `<b>Produtos monitorados</b>\n${lines.join('\n')}`;
    }

    case '/pausar':
    case '/ativar': {
      const p = find(args[0]);
      if (!p) return unknown(args[0]);
      const active = cmd === '/ativar';
      store.overrides[p.id] = { ...store.overrides[p.id], active };
      return `${active ? '🟢 Ativado' : '⏸ Pausado'}: ${esc(p.label)}`;
    }

    case '/teto': {
      const p = find(args[0]);
      if (!p) return unknown(args[0]);
      const v = parseMoney(args[1]);
      if (v === null) return 'Uso: <code>/teto id valor</code>, ex. <code>/teto iphone-17 4500</code>';
      if (v <= (p.minPrice || 0)) return `O teto precisa ser maior que o mínimo atual (${brl(p.minPrice)}). Ajuste com /minimo.`;
      store.overrides[p.id] = { ...store.overrides[p.id], maxPrice: v };
      return `💰 Teto de ${esc(p.label)}: ${brl(v)}`;
    }

    case '/minimo': {
      // O mínimo separa o produto de capas e acessórios; baixar demais faz
      // acessório virar alerta, por isso a resposta lembra o efeito
      const p = find(args[0]);
      if (!p) return unknown(args[0]);
      const raw = args[1] === '0' ? 0 : parseMoney(args[1]);
      if (raw === null || raw === undefined) return 'Uso: <code>/minimo id valor</code>, ex. <code>/minimo controle 200</code>';
      if (raw >= p.maxPrice) return `O mínimo precisa ser menor que o teto atual (${brl(p.maxPrice)}). Ajuste com /teto.`;
      store.overrides[p.id] = { ...store.overrides[p.id], minPrice: raw };
      return `🔻 Mínimo de ${esc(p.label)}: ${brl(raw)}\n<i>Abaixo disso o post é tratado como acessório (capa, película, peça).</i>`;
    }

    case '/add': {
      const { product, error } = buildCustomProduct(args);
      if (error) return error;
      if (find(product.id)) return `Já existe <code>${esc(product.id)}</code>. Use /teto ou /ativar.`;
      store.custom.push(product);
      const ex = args.filter((a) => a.startsWith('-')).join(' ');
      return `➕ Monitorando <b>${esc(product.label)}</b> (<code>${esc(product.id)}</code>)\n` +
        `Teto ${brl(product.maxPrice)}, mínimo ${brl(product.minPrice)}${ex ? `, excluindo ${esc(ex)}` : ''}`;
    }

    case '/remover': {
      const id = (args[0] || '').toLowerCase();
      if (!store.custom.some((p) => p.id === id)) {
        return find(id) ? 'Produtos do catálogo-base não são removidos pelo bot. Use /pausar.' : unknown(id);
      }
      store.custom = store.custom.filter((p) => p.id !== id);
      delete store.overrides[id];
      return `🗑 Removido: <code>${esc(id)}</code>`;
    }

    case '/status': {
      const l = ctx.listener || {};
      const active = catalog.filter((p) => p.active !== false).length;
      return [
        '<b>Status do radar</b>',
        `Listener no ar desde ${l.started_at ? new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(Date.parse(l.started_at)) : '?'}`,
        `Último post recebido: ${ago(l.last_message_at, now)}`,
        `Posts desde o início: ${l.messages_since_start ?? '?'}`,
        `Produtos ativos: ${active} de ${catalog.length}`,
      ].join('\n');
    }

    default:
      return `Comando não reconhecido.\n\n${HELP}`;
  }
}

if (typeof module !== 'undefined') module.exports = { handleCommand, buildCustomProduct };

if (typeof $input !== 'undefined') {
  const store = $getWorkflowStaticData('global');
  const { catalog } = $('Catálogo de produtos').first().json;
  const body = $('Comando do bot').first().json.body;
  return [{ json: { text: handleCommand(body.text, store, { catalog, listener: body.listener }) } }];
}
